const queryClient = new QueryClient();
type Workflow = { device: DeviceInput | null; saved?: Device; diagnostics?: DiagnosticResult; value?: Valuation; sanitation?: SanitizationRecord; routing?: RoutingResult };
const FlowContext = createContext<{ flow: Workflow; setFlow: (flow: Workflow) => void; device: DeviceInput; setDevice: (d: DeviceInput) => void }>({
  flow: { device: null }, setFlow: () => {}, device: blankDevice(), setDevice: () => {},
});
function blankDevice(): DeviceInput {
  return { category: DeviceCategory.Smartphone, brand: '', model: '', condition: Condition.WORKING, powersOn: true, hasPersonalData: true, source: DeviceInputSource.USER_REPORTED, location: 'Bengaluru' };
}
