            <div style={{height:103,borderRadius:15,background:'#294d41',color:'#e4ebce',display:'flex',alignItems:'center',justifyContent:'space-between',padding:'0 17px'}}><div><div className="eyebrow" style={{color:'#a9bd86'}}>ESTIMATED RESALE</div><b className="mono" style={{fontSize:21,display:'block',marginTop:9}}>₹ 12,400</b></div><ArrowUpRightIcon/></div>
